"use client"

import { EditViewer } from "@/components/viewers/edit/edit-viewer"
import type { FormField } from "@/components/viewers/lib/edit-types"
import editSample from "@/components/viewers/sample-data/edit.json"

const ORIGINAL_PDF_URL = "/samples/fidelity-edit/fidelity_original.pdf"

// A template-fill of the Fidelity "Bank Wire Authorization" form: 29 detected
// form fields across 3 pages, each with a normalized bbox and an inferred value.
const EDIT_FIELDS = editSample as FormField[]

/**
 * Edit viewer block — detected fields beside the source document, linked by
 * their bbox. `EditViewer` owns the mode switcher, overlay preview, search,
 * filters, and page grouping. Hover or select a field to highlight its region on
 * the page and scroll it into view.
 */
export function EditViewerBlock() {
  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <EditViewer
        result={{ fields: EDIT_FIELDS }}
        sourceDocument={{
          src: ORIGINAL_PDF_URL,
          mimeType: "application/pdf",
          filename: "fidelity-bank-wire-authorization.pdf",
        }}
      />
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import type { PageOverlayProps } from "@/components/ui/pdf-viewer"

import { EditViewerDocumentPane } from "./edit-viewer-document-pane"
import { EditViewerFieldPanel } from "./edit-viewer-field-panel"
import { EditFieldOverlayLayer } from "./edit-viewer-overlays"
import {
  EditViewerBusyOverlay,
  EmptyEditViewerState,
} from "./edit-viewer-states"
import { EditViewerToolbar } from "./edit-viewer-toolbar"
import type { EditViewerProps } from "./edit-viewer-types"
import { useEditViewerController } from "./use-edit-viewer-controller"

export type {
  EditViewerDocument,
  EditViewerField,
  EditViewerInputField,
  EditViewerInputResult,
  EditViewerMode,
  EditViewerOptions,
  EditViewerProps,
  EditViewerResult,
  EditViewerStatus,
} from "./edit-viewer-types"

export function EditViewer({
  result,
  sourceDocument,
  filledDocument,
  mode,
  onModeChange,
  selectedFieldKey,
  onSelectedFieldKeyChange,
  status = { state: "idle" },
  className,
  options,
}: EditViewerProps) {
  const controller = useEditViewerController({
    result,
    sourceDocument,
    filledDocument,
    mode,
    onModeChange,
    selectedFieldKey,
    onSelectedFieldKeyChange,
    status,
    options,
  })

  const renderPageOverlay = React.useCallback(
    ({ pageNumber }: PageOverlayProps) => (
      <EditFieldOverlayLayer
        fieldsByPage={controller.fieldsByPage}
        pageNumber={pageNumber}
        mode={controller.activeMode}
        effectiveFieldKey={controller.effectiveFieldKey}
        onFieldHover={controller.setHoveredFieldKey}
        onFieldSelect={controller.selectField}
      />
    ),
    [
      controller.activeMode,
      controller.effectiveFieldKey,
      controller.fieldsByPage,
      controller.selectField,
      controller.setHoveredFieldKey,
    ]
  )

  return (
    <div
      data-edit-viewer-root
      className={cn(
        "relative flex min-h-0 w-full flex-1 flex-col overflow-hidden bg-background md:flex-row",
        className
      )}
    >
      {status.state === "detecting" || status.state === "filling" ? (
        <EditViewerBusyOverlay status={status} />
      ) : null}

      {!controller.hasOutput ? (
        <EmptyEditViewerState />
      ) : (
        <>
          <div className="relative flex min-w-0 flex-1 flex-col">
            <EditViewerToolbar
              modes={controller.availableModes}
              mode={controller.activeMode}
              onModeChange={controller.changeMode}
              filledCount={controller.filledCount}
              fieldCount={controller.fields.length}
              status={controller.activeStatus}
            />
            <div className="relative min-h-0 flex-1">
              <EditViewerDocumentPane
                mode={controller.activeMode}
                sourceDocument={sourceDocument}
                filledDocument={filledDocument}
                renderPageOverlay={renderPageOverlay}
                viewerRef={controller.viewerRef}
                status={status}
              />
            </div>
          </div>

          {controller.resolvedOptions.fieldPanel ? (
            <EditViewerFieldPanel
              fields={controller.fields}
              filledCount={controller.filledCount}
              effectiveFieldKey={controller.effectiveFieldKey}
              selectedFieldKey={controller.selectedFieldKey}
              query={controller.query}
              onQueryChange={controller.setQuery}
              filter={controller.filter}
              onFilterChange={controller.setFilter}
              onFieldHover={controller.setHoveredFieldKey}
              onFieldSelect={controller.selectField}
              showSearch={controller.resolvedOptions.search}
              showFilters={controller.resolvedOptions.filters}
            />
          ) : null}
        </>
      )}
    </div>
  )
}

import type { BBox } from "@/components/viewers/lib/edit-types"

export type EditViewerMode = "source" | "preview" | "filled"

export type EditViewerStatus =
  | { state: "idle" }
  | { state: "detecting"; message?: string }
  | { state: "filling"; message?: string }
  | { state: "error"; message: string }

export interface EditViewerOptions {
  fieldPanel?: boolean
  search?: boolean
  filters?: boolean
  preview?: boolean
  filledOutput?: boolean
}

export interface EditViewerField {
  key: string
  description?: string
  type: "text" | "checkbox"
  value?: string | boolean | null
  bbox?: BBox
  combing?: boolean
  maxLength?: number
}

export interface EditViewerResult {
  fields: EditViewerField[]
  editType?: "agent" | "template"
}

export interface EditViewerInputField {
  key?: string
  description?: string
  type?: "text" | "checkbox"
  value?: string | boolean | null
  bbox?: BBox
  combing?: boolean
  maxLength?: number
  max_length?: number
}

export interface EditViewerInputResult {
  fields?: readonly EditViewerInputField[] | null
  editType?: "agent" | "template"
}

export interface EditViewerDocument {
  buffer?: ArrayBuffer | null
  src?: string | null
  mimeType: string
  filename?: string
}

export interface EditViewerProps {
  result: EditViewerInputResult | null
  sourceDocument?: EditViewerDocument | null
  filledDocument?: EditViewerDocument | null
  mode?: EditViewerMode
  onModeChange?: (mode: EditViewerMode) => void
  selectedFieldKey?: string | null
  onSelectedFieldKeyChange?: (key: string | null) => void
  status?: EditViewerStatus
  className?: string
  options?: EditViewerOptions
}

import type { BBox } from "@/components/viewers/lib/edit-types"

import type {
  EditViewerDocument,
  EditViewerField,
  EditViewerInputField,
  EditViewerInputResult,
  EditViewerMode,
  EditViewerOptions,
  EditViewerResult,
} from "./edit-viewer-types"

export type EditViewerFilter =
  | "all"
  | "filled"
  | "empty"
  | "text"
  | "checkbox"
  | "no_location"

export interface EditViewerModeInput {
  fields: readonly EditViewerField[]
  sourceDocument?: EditViewerDocument | null
  filledDocument?: EditViewerDocument | null
  options: Required<EditViewerOptions>
}

const DEFAULT_OPTIONS: Required<EditViewerOptions> = {
  fieldPanel: true,
  search: true,
  filters: true,
  preview: true,
  filledOutput: true,
}

const MODE_FALLBACK_ORDER: EditViewerMode[] = ["filled", "preview", "source"]

const MODE_DISPLAY_ORDER: EditViewerMode[] = ["source", "preview", "filled"]

export function resolveEditViewerOptions(
  options: EditViewerOptions | undefined
): Required<EditViewerOptions> {
  return { ...DEFAULT_OPTIONS, ...options }
}

export function normalizeEditViewerResult(
  result: EditViewerInputResult | null | undefined
): EditViewerResult {
  const fields = result?.fields ?? []
  return {
    fields: fields.map(normalizeEditViewerField),
    editType: result?.editType,
  }
}

function normalizeEditViewerField(
  field: EditViewerInputField,
  index: number
): EditViewerField {
  const key = field.key || `field_${index}`
  return {
    key,
    description: field.description || key || `Field ${index + 1}`,
    type: field.type === "checkbox" ? "checkbox" : "text",
    value: normalizeFieldValue(field.value),
    bbox: field.bbox ? normalizeBBox(field.bbox) : undefined,
    combing: field.combing,
    maxLength: normalizeMaxLength(field),
  }
}

function normalizeFieldValue(value: string | boolean | null | undefined) {
  if (typeof value === "boolean") return value
  if (value === null || value === undefined) return null
  return String(value)
}

function normalizeMaxLength(field: EditViewerInputField) {
  if ("maxLength" in field && typeof field.maxLength === "number") {
    return field.maxLength
  }
  if ("max_length" in field && typeof field.max_length === "number") {
    return field.max_length
  }
  return undefined
}

function normalizeBBox(bbox: BBox): BBox | undefined {
  const page = Number(bbox.page)
  const left = Number(bbox.left)
  const top = Number(bbox.top)
  const width = Number(bbox.width)
  const height = Number(bbox.height)

  if (
    !Number.isFinite(page) ||
    !Number.isFinite(left) ||
    !Number.isFinite(top) ||
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    page < 1 ||
    width <= 0 ||
    height <= 0
  ) {
    return undefined
  }

  const normalizedLeft = clamp01(left)
  const normalizedTop = clamp01(top)
  const normalizedWidth = Math.min(clamp01(width), 1 - normalizedLeft)
  const normalizedHeight = Math.min(clamp01(height), 1 - normalizedTop)

  if (normalizedWidth <= 0 || normalizedHeight <= 0) return undefined

  return {
    page: Math.round(page),
    left: normalizedLeft,
    top: normalizedTop,
    width: normalizedWidth,
    height: normalizedHeight,
  }
}

function clamp01(value: number) {
  if (!Number.isFinite(value)) return 0
  return Math.max(0, Math.min(1, value))
}

export function isEditFieldChecked(field: EditViewerField) {
  if (typeof field.value === "boolean") return field.value
  if (typeof field.value !== "string") return false
  const value = field.value.trim().toLowerCase()
  return (
    value === "true" || value === "checked" || value === "yes" || value === "1"
  )
}

export function isEditFieldFilled(field: EditViewerField) {
  if (field.type === "checkbox") return isEditFieldChecked(field)
  return Boolean(
    typeof field.value === "string"
      ? field.value.trim().length > 0
      : field.value !== null && field.value !== undefined
  )
}

export function displayEditFieldValue(field: EditViewerField): string {
  if (field.type === "checkbox") {
    return isEditFieldChecked(field) ? "Checked" : "Unchecked"
  }
  if (field.value === null || field.value === undefined) return ""
  return String(field.value).trim()
}

export function deriveEditViewerModes(input: EditViewerModeInput) {
  const hasLocatedFields = input.fields.some((field) => Boolean(field.bbox))
  const hasSource = Boolean(input.sourceDocument)
  const filledOutputAvailable = Boolean(input.filledDocument)
  const modes: EditViewerMode[] = []

  if (hasSource) {
    modes.push("source")
  }

  if (
    input.options.preview &&
    hasSource &&
    hasLocatedFields &&
    input.sourceDocument &&
    canPreviewEditViewerDocument(input.sourceDocument)
  ) {
    modes.push("preview")
  }

  if (input.options.filledOutput && filledOutputAvailable) {
    modes.push("filled")
  }

  return sortModes(modes)
}

function sortModes(modes: EditViewerMode[]) {
  const rank = new Map(MODE_DISPLAY_ORDER.map((mode, index) => [mode, index]))
  return Array.from(new Set(modes)).sort(
    (a, b) => (rank.get(a) ?? 99) - (rank.get(b) ?? 99)
  )
}

export function resolveEditViewerMode({
  availableModes,
  requestedMode,
  currentMode,
}: {
  availableModes: readonly EditViewerMode[]
  requestedMode?: EditViewerMode | null
  currentMode?: EditViewerMode | null
}): EditViewerMode | null {
  if (requestedMode && availableModes.includes(requestedMode)) {
    return requestedMode
  }
  if (currentMode && availableModes.includes(currentMode)) {
    return currentMode
  }
  return (
    MODE_FALLBACK_ORDER.find((mode) => availableModes.includes(mode)) ?? null
  )
}

export function filterEditViewerFields({
  fields,
  query,
  filter,
}: {
  fields: readonly EditViewerField[]
  query?: string
  filter?: EditViewerFilter
}) {
  const normalizedQuery = (query ?? "").trim().toLowerCase()
  const resolvedFilter = filter ?? "all"

  return fields.filter((field) => {
    if (resolvedFilter === "filled" && !isEditFieldFilled(field)) return false
    if (resolvedFilter === "empty" && isEditFieldFilled(field)) return false
    if (resolvedFilter === "text" && field.type !== "text") return false
    if (resolvedFilter === "checkbox" && field.type !== "checkbox") {
      return false
    }
    if (resolvedFilter === "no_location" && field.bbox) return false
    if (!normalizedQuery) return true
    return (
      field.key.toLowerCase().includes(normalizedQuery) ||
      (field.description ?? "").toLowerCase().includes(normalizedQuery) ||
      displayEditFieldValue(field).toLowerCase().includes(normalizedQuery)
    )
  })
}

export interface EditViewerFieldGroup {
  key: string
  label: string
  page: number | null
  fields: EditViewerField[]
}

export function groupEditViewerFieldsByPage(
  fields: readonly EditViewerField[]
): EditViewerFieldGroup[] {
  const pageGroups = groupLocatedEditViewerFieldsByPage(fields)
  const unlocatedFields: EditViewerField[] = []

  for (const field of fields) {
    if (!field.bbox) {
      unlocatedFields.push(field)
    }
  }

  const groups: EditViewerFieldGroup[] = Array.from(pageGroups.entries())
    .sort((a, b) => a[0] - b[0])
    .map(([page, pageFields]) => ({
      key: `page:${page}`,
      label: `Page ${page}`,
      page,
      fields: pageFields,
    }))

  if (unlocatedFields.length > 0) {
    groups.push({
      key: "no-location",
      label: "No location",
      page: null,
      fields: unlocatedFields,
    })
  }

  return groups
}

export function groupLocatedEditViewerFieldsByPage(
  fields: readonly EditViewerField[]
): Map<number, EditViewerField[]> {
  const pageGroups = new Map<number, EditViewerField[]>()

  for (const field of fields) {
    if (!field.bbox) continue
    const pageFields = pageGroups.get(field.bbox.page) ?? []
    pageFields.push(field)
    pageGroups.set(field.bbox.page, pageFields)
  }

  return pageGroups
}

export function canPreviewEditViewerDocument(document: EditViewerDocument) {
  const filename = document.filename ?? ""
  return (
    document.mimeType.toLowerCase().includes("application/pdf") ||
    filename.toLowerCase().endsWith(".pdf")
  )
}

import type { EditViewerField } from "./edit-viewer-types"

export const EDIT_FIELD_ACCENTS: Record<
  EditViewerField["type"],
  { line: string; tint: string; text: string; badge: string }
> = {
  text: {
    line: "var(--color-chart-3)",
    tint: "color-mix(in oklab, var(--color-chart-3) 12%, transparent)",
    text: "var(--color-chart-4)",
    badge: "border-chart-3/30 bg-chart-3/10 text-chart-4 dark:text-chart-2",
  },
  checkbox: {
    line: "var(--color-amber-500)",
    tint: "color-mix(in oklab, var(--color-amber-500) 14%, transparent)",
    text: "var(--color-amber-600)",
    badge: "border-warning/30 bg-warning/10 text-warning-foreground",
  },
}

import * as React from "react"

import type { PdfViewerHandle } from "@/components/ui/pdf-viewer"

import {
  deriveEditViewerModes,
  groupLocatedEditViewerFieldsByPage,
  isEditFieldFilled,
  normalizeEditViewerResult,
  resolveEditViewerMode,
  resolveEditViewerOptions,
  type EditViewerFilter,
} from "./edit-viewer-model"
import type {
  EditViewerField,
  EditViewerMode,
  EditViewerProps,
} from "./edit-viewer-types"

export function useEditViewerController({
  result,
  sourceDocument,
  filledDocument,
  mode,
  onModeChange,
  selectedFieldKey,
  onSelectedFieldKeyChange,
  status,
  options,
}: Pick<
  EditViewerProps,
  | "result"
  | "sourceDocument"
  | "filledDocument"
  | "mode"
  | "onModeChange"
  | "selectedFieldKey"
  | "onSelectedFieldKeyChange"
  | "options"
> & {
  status: NonNullable<EditViewerProps["status"]>
}) {
  const viewerRef = React.useRef<PdfViewerHandle>(null)
  const resolvedOptions = React.useMemo(
    () => resolveEditViewerOptions(options),
    [options]
  )
  const editResult = React.useMemo(
    () => normalizeEditViewerResult(result),
    [result]
  )
  const fields = editResult.fields
  const fieldsByPage = React.useMemo(
    () => groupLocatedEditViewerFieldsByPage(fields),
    [fields]
  )
  const availableModes = React.useMemo(
    () =>
      deriveEditViewerModes({
        fields,
        sourceDocument,
        filledDocument,
        options: resolvedOptions,
      }),
    [fields, filledDocument, resolvedOptions, sourceDocument]
  )

  const [uncontrolledMode, setUncontrolledMode] =
    React.useState<EditViewerMode | null>(null)
  const activeMode = resolveEditViewerMode({
    availableModes,
    requestedMode: mode,
    currentMode: uncontrolledMode,
  })

  React.useEffect(() => {
    if (mode || uncontrolledMode === activeMode) return
    setUncontrolledMode(activeMode)
  }, [activeMode, mode, uncontrolledMode])

  const [internalSelectedFieldKey, setInternalSelectedFieldKey] =
    React.useState<string | null>(null)
  const [hoveredFieldKey, setHoveredFieldKey] = React.useState<string | null>(
    null
  )
  const [query, setQuery] = React.useState("")
  const [filter, setFilter] = React.useState<EditViewerFilter>("all")

  const selectedFieldKeyValue = selectedFieldKey ?? internalSelectedFieldKey
  const effectiveFieldKey = hoveredFieldKey ?? selectedFieldKeyValue
  const fieldByKey = React.useMemo(() => createFieldMap(fields), [fields])

  React.useEffect(() => {
    if (!selectedFieldKeyValue || fieldByKey.has(selectedFieldKeyValue)) return
    if (selectedFieldKey === undefined) setInternalSelectedFieldKey(null)
    onSelectedFieldKeyChange?.(null)
  }, [
    fieldByKey,
    onSelectedFieldKeyChange,
    selectedFieldKey,
    selectedFieldKeyValue,
  ])

  const filledCount = React.useMemo(
    () => fields.filter(isEditFieldFilled).length,
    [fields]
  )
  const setSelectedFieldKey = React.useCallback(
    (nextSelectedFieldKey: string | null) => {
      if (selectedFieldKey === undefined) {
        setInternalSelectedFieldKey(nextSelectedFieldKey)
      }
      onSelectedFieldKeyChange?.(nextSelectedFieldKey)
    },
    [onSelectedFieldKeyChange, selectedFieldKey]
  )
  const selectField = React.useCallback(
    (nextSelectedFieldKey: string) => {
      setSelectedFieldKey(nextSelectedFieldKey)
      const field = fieldByKey.get(nextSelectedFieldKey)
      if (!field?.bbox) return
      viewerRef.current?.scrollToPageArea({
        pageNumber: field.bbox.page,
        top: field.bbox.top * 100,
      })
    },
    [fieldByKey, setSelectedFieldKey]
  )
  const changeMode = React.useCallback(
    (nextMode: EditViewerMode) => {
      if (!availableModes.includes(nextMode)) return
      setUncontrolledMode(nextMode)
      onModeChange?.(nextMode)
    },
    [availableModes, onModeChange]
  )

  return {
    activeMode,
    activeStatus: status.state === "idle" ? null : status,
    availableModes,
    changeMode,
    effectiveFieldKey,
    fields,
    fieldsByPage,
    filledCount,
    filter,
    hasOutput:
      status.state === "error" ||
      availableModes.length > 0 ||
      fields.length > 0,
    query,
    resolvedOptions,
    selectedFieldKey: selectedFieldKeyValue,
    selectField,
    setFilter,
    setHoveredFieldKey,
    setQuery,
    viewerRef,
  }
}

function createFieldMap(fields: EditViewerField[]) {
  const fieldByKey = new Map<string, EditViewerField>()
  for (const field of fields) fieldByKey.set(field.key, field)
  return fieldByKey
}

import { AlertCircle, FileText, Loader2, Pencil } from "lucide-react"

import type { EditViewerStatus } from "./edit-viewer-types"

export function EditViewerBusyOverlay({
  status,
}: {
  status: Extract<EditViewerStatus, { state: "detecting" | "filling" }>
}) {
  return (
    <div
      className="absolute inset-0 z-20 flex items-center justify-center bg-background/80 backdrop-blur-sm"
      role="status"
      aria-live="polite"
    >
      <div className="flex flex-col items-center gap-2">
        <Loader2 className="size-6 animate-spin text-muted-foreground" />
        <span className="text-sm text-muted-foreground">
          {status.message ??
            (status.state === "detecting"
              ? "Detecting form fields..."
              : "Filling document...")}
        </span>
      </div>
    </div>
  )
}

export function EmptyEditViewerState() {
  return (
    <div className="flex flex-1 flex-col items-center justify-center gap-4 bg-muted px-8 text-muted-foreground">
      <Pencil className="size-16 text-muted-foreground/70" />
      <p className="text-center text-base">Run edit to see output</p>
      <p className="max-w-sm text-center text-sm text-muted-foreground/80">
        Upload a document, add filling instructions, and click Run Edit
      </p>
    </div>
  )
}

export function NoDocumentState({ message }: { message: string }) {
  return (
    <div className="flex h-full min-h-[280px] flex-col items-center justify-center gap-3 bg-muted px-6 text-center text-muted-foreground">
      <FileText className="size-10 text-muted-foreground/70" />
      <p className="text-sm">{message}</p>
    </div>
  )
}

export function EditViewerErrorState({ message }: { message: string }) {
  return (
    <div
      className="flex h-full min-h-[280px] flex-col items-center justify-center gap-3 bg-muted px-6 text-center"
      role="alert"
    >
      <AlertCircle className="size-10 text-destructive" />
      <p className="max-w-md text-sm text-destructive">{message}</p>
    </div>
  )
}

export function EditViewerStatusBadge({
  status,
}: {
  status: Exclude<EditViewerStatus, { state: "idle" }>
}) {
  if (status.state === "error") {
    return (
      <span className="inline-flex items-center gap-1 rounded border border-destructive/30 bg-destructive/10 px-2 py-0.5 text-xs text-destructive">
        <AlertCircle className="size-3" />
        {status.message}
      </span>
    )
  }

  return (
    <span className="inline-flex items-center gap-1 rounded border border-border bg-muted px-2 py-0.5 text-xs text-muted-foreground">
      <Loader2 className="size-3 animate-spin" />
      {status.message ??
        (status.state === "detecting"
          ? "Detecting fields"
          : "Filling document")}
    </span>
  )
}

import { FileText } from "lucide-react"

import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"

import { EditViewerStatusBadge } from "./edit-viewer-states"
import type { EditViewerMode, EditViewerStatus } from "./edit-viewer-types"

const MODE_LABELS: Record<EditViewerMode, string> = {
  source: "Source",
  preview: "Preview",
  filled: "Filled",
}

export function EditViewerToolbar({
  modes,
  mode,
  onModeChange,
  filledCount,
  fieldCount,
  status,
}: {
  modes: EditViewerMode[]
  mode: EditViewerMode | null
  onModeChange: (mode: EditViewerMode) => void
  filledCount: number
  fieldCount: number
  status: Exclude<EditViewerStatus, { state: "idle" }> | null
}) {
  if (modes.length === 0) return null

  return (
    <div className="flex min-h-10 flex-shrink-0 flex-wrap items-center gap-3 border-b bg-background px-3 py-1.5">
      {modes.length > 1 && mode ? (
        <Tabs
          value={mode}
          onValueChange={(value) => onModeChange(value as EditViewerMode)}
        >
          <TabsList variant="underline" className="py-0">
            {modes.map((availableMode) => (
              <TabsTrigger
                key={availableMode}
                value={availableMode}
                className="h-9 text-xs sm:text-xs"
                aria-label={`${MODE_LABELS[availableMode]} view`}
              >
                {MODE_LABELS[availableMode]}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
      ) : (
        <div className="flex items-center gap-2 text-sm font-medium">
          <FileText className="size-4 text-muted-foreground" />
          {mode ? MODE_LABELS[mode] : "Edit output"}
